    digitalWrite(LED[i], HIGH);
    delay(120);
    digitalWrite(LED[i], LOW);
  }

  // SIKLSIZ bu 20 qator bo'lardi:
  //   digitalWrite(5,HIGH); delay(120); digitalWrite(5,LOW);
  //   digitalWrite(6,HIGH); delay(120); digitalWrite(6,LOW);  ... va h.k.
}

